using System.Reflection;
var type=typeof(Example);Console.WriteLine(new Example().GetType()==type);Console.WriteLine(type.GetProperty("Missing") is null);
var method=type.GetMethod("Say",new[]{typeof(string)})!;Console.WriteLine(method.Invoke(new Example(),new object[]{"An"}));
var mark=type.GetCustomAttribute<LabelAttribute>();Console.WriteLine(mark?.Text);
try{type.GetMethod("Fail")!.Invoke(new Example(),null);}
catch(TargetInvocationException ex){Console.WriteLine(ex.InnerException?.GetType().Name);}
[AttributeUsage(AttributeTargets.Class)]class LabelAttribute(string text):Attribute{public string Text=>text;}
[Label("đọc metadata")]class Example{public string Say(string s)=>s;public string Say(int n)=>n.ToString();public void Fail()=>throw new InvalidOperationException("demo");}

